module Stocktally
  Entry = Struct.new(:sku, :delta, :bin, :note)

  class Ledger
    attr_reader :entries

    def initialize
      @entries = []
    end

    def record(sku, delta, bin: "A", note: nil)
      @entries << Entry.new(sku, delta, bin, note)
      self
    end

    def balance(sku)
      @entries.select { |e| e.sku == sku }.sum(&:delta)
    end

    def skus
      @entries.map(&:sku).uniq.sort
    end

    def notes_by_bin
      groups = Hash.new([])
      @entries.each { |e| groups[e.bin] << e.note if e.note }
      groups
    end

    def snapshot
      @entries.map(&:dup)
    end
  end
end

